import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Returns priority with which we want to add item to each bin.
    Args:
        item: Size of item to be added to the bin.
        bins: Array of capacities for each bin.
    Return:
        Array of same size as bins with priority score of each bin.
    """
    rem = bins - item
    valid = rem >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    valid_rem = np.where(valid, rem, -np.inf)
    unique_rems = np.sort(np.unique(valid_rem[valid]))
    if len(unique_rems) >= 3:
        target_rem = unique_rems[-3]
    elif len(unique_rems) == 2:
        target_rem = unique_rems[0]
    else:
        target_rem = unique_rems[0]
    return np.where(rem == target_rem, 0.0, np.where(valid, -abs(rem - target_rem), -np.inf))

